content.text:
{
  "name": "质量流量控制器",
  "name_en": "Mass Flow Controller",
  "manufacturer": "",
  "description": "质量流量控制器用于精确设定和测量气体的质量流量，常用于实验室气体输送、反应气氛配比、管式炉进气控制和一般过程流量调节。",
  "description_en": "A mass flow controller is used to precisely set and measure gas mass flow. It is commonly used in laboratories for gas delivery, reaction atmosphere mixing, tube furnace gas inlet control, and general process flow regulation.",
  "tag_hints": [
    "mass flow control",
    "gas delivery",
    "process gas regulation",
    "reaction atmosphere control",
    "MFC",
    "serial-addressable instrument"
  ],
  "actions": [
    {
      "action_name": "auto-SetFlow",
      "description": "设置质量流量设定值。",
      "description_en": "Set the mass flow setpoint."
    },
    {
      "action_name": "auto-ChangeAddress",
      "description": "修改设备的串口通信地址。",
      "description_en": "Change the device serial communication address."
    },
    {
      "action_name": "auto-QueryFlow",
      "description": "查询当前测得的质量流量。",
      "description_en": "Query the currently measured mass flow rate."
    },
    {
      "action_name": "auto-QueryOpMode",
      "description": "查询设备当前运行模式。",
      "description_en": "Query the device's current operating mode."
    }
  ]
}

